package com.codepilot1c.core.edt.infobase;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class NativeUpdateInteractionTest {
 @Test public void recognizesOnlyExclusiveAccessQuestionWithExplicitNativeRetryAndCancel(){assertTrue(NativeUpdateInteraction.exclusiveQuestion("Ошибка исключительной блокировки информационной базы",List.of("Отмена","Повторить","Обновить динамически")));assertTrue(NativeUpdateInteraction.exclusiveQuestion("Exclusive lock required",List.of("Cancel","&Retry")));assertFalse(NativeUpdateInteraction.exclusiveQuestion("Permission to load binary files?",List.of("Cancel","Retry")));assertFalse(NativeUpdateInteraction.exclusiveQuestion("Exclusive lock required",List.of("Cancel","Retry","Allow access")));assertFalse(NativeUpdateInteraction.exclusiveQuestion("Exclusive lock required",List.of("Cancel","Retry","Retry")));}
 @Test public void applicationUpdateDecisionRequiresExactProjectAndKnownChoices(){var labels=List.of("Обновить и запустить","Запустить без обновления","Отменить");assertTrue(NativeUpdateInteraction.applicationQuestion("Конфигурация не синхронизирована с проектом TestProject",labels,"TestProject"));assertFalse(NativeUpdateInteraction.applicationQuestion("Конфигурация не синхронизирована с проектом Other",labels,"TestProject"));assertFalse(NativeUpdateInteraction.applicationQuestion("Security permission for TestProject",labels,"TestProject"));assertFalse(NativeUpdateInteraction.applicationQuestion("TestProject not synchronized",List.of("Allow","Deny","Cancel"),"TestProject"));}
 @Test public void dynamicAnswerIsOfferedOnlyForOneEnabledExclusiveButton(){var button=Map.of("label","Обновить динамически","enabled",true);assertTrue(NativeUpdateInteraction.dynamicAvailable(Map.of("kind","exclusive_access","choices",List.of(button))));assertFalse(NativeUpdateInteraction.dynamicAvailable(Map.of("kind","application_update","choices",List.of(button))));assertFalse(NativeUpdateInteraction.dynamicAvailable(Map.of("kind","exclusive_access","choices",List.of(Map.of("label","Обновить динамически","enabled",false)))));assertFalse(NativeUpdateInteraction.dynamicAvailable(Map.of("kind","exclusive_access","choices",List.of(button,button))));}

}
